<script setup lang="ts">import { onMounted, ref } from "vue"; import { ElMessage } from "element-plus"; import { get, post } from "@/api/client"; import type { WorkflowTask } from "@/types"; const tasks = ref<readonly WorkflowTask[]>([]); onMounted(async () => { tasks.value = await get<readonly WorkflowTask[]>("/workflow-tasks?mine=true") }); async function complete(id: string): Promise<void> { await post(`/workflow-tasks/${id}/complete`, { action: "approve" }); tasks.value = tasks.value.filter((task) => task.id !== id); ElMessage.success("任务已完成") }</script>
<template><el-card><template #header>待办任务</template><el-table :data="tasks" border><el-table-column prop="id" label="任务 ID" /><el-table-column prop="title" label="标题" /><el-table-column prop="status" label="状态" /><el-table-column label="操作"><template #default="scope"><el-button type="primary" link @click="complete(scope.row.id)">完成</el-button></template></el-table-column></el-table></el-card></template>
